import * as T from 'three';
export function buildRope2D(group,p,own){const count=p.particles,positions=new Float32Array(count*6),normal=new Float32Array(count*6),uv=new Float32Array(count*4),indices=new Uint32Array((count-1)*6),points=new Float32Array(count*3),point=new T.Vector3(),end=new T.Vector3(...p.end);for(let i=0;i<count;i++){point.fromArray(p.start).lerp(end,i/(count-1)).toArray(points,i*3);uv.set([i/(count-1),0,i/(count-1),1],i*4);normal[i*6+2]=normal[i*6+5]=1;if(i<count-1)indices.set([i*2,i*2+1,i*2+2,i*2+1,i*2+3,i*2+2],i*6);}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3).setUsage(T.DynamicDrawUsage));geometry.setAttribute('normal',new T.BufferAttribute(normal,3));geometry.setAttribute('uv',new T.BufferAttribute(uv,2));geometry.setIndex(new T.BufferAttribute(indices,1));const material=new T.MeshBasicMaterial({color:0xd3b981,side:T.DoubleSide}),mesh=new T.Mesh(geometry,material);mesh.userData.rope2d=true;own(group,geometry);own(group,material);group.add(mesh);group.userData.ropeMesh={geometry,p,rest:points,point,inverse:new T.Matrix4(),version:null};updateRope2D(group,false);}
export function updateRope2D(group,running){const state=group.userData.ropeMesh;if(!state)return;const frame=running?group.userData.ropeFrame:null,version=frame?.version??-1;if(state.version===version&&state.generation===frame?.generation)return;const points=frame?.positions||state.rest,count=state.p.particles;if(points.length!==count*3)return;const out=state.geometry.attributes.position.array;state.inverse.copy(group.matrixWorld).invert();for(let i=0;i<count;i++){const prev=Math.max(0,i-1)*3,next=Math.min(count-1,i+1)*3,dx=points[next]-points[prev],dy=points[next+1]-points[prev+1],length=Math.hypot(dx,dy)||1,nx=-dy/length*state.p.renderWidth/2,ny=dx/length*state.p.renderWidth/2;for(let side=0;side<2;side++){state.point.set(points[i*3]+(side?nx:-nx),points[i*3+1]+(side?ny:-ny),points[i*3+2]);if(frame)state.point.applyMatrix4(state.inverse);state.point.toArray(out,i*6+side*3);}}state.geometry.attributes.position.needsUpdate=true;state.geometry.computeBoundingSphere();state.geometry.computeBoundingBox();state.version=version;state.generation=frame?.generation;}
